import sys
(n, k) = input().strip().split(' ')
(n, k) = [int(n), int(k)]
x = [int(x_temp) for x_temp in input().strip().split(' ')]
x.sort()
s = set(x)
minx = x[0]
maxx = x[-1]
d = dict(zip(range(minx, maxx + 1), [False] * (maxx - minx + 1)))
cnt = 0
for xi in x:
	if d[xi]:
		continue
	if xi + k in s:
		cnt += 1
		for i in range(xi, xi + 2 * k + 1):
			d[i] = True
	else:
		for i in range(xi + k, xi - 1, -1):
			if i in s:
				for j in range(xi, i + k + 1):
					d[j] = True
				cnt += 1
				break
print(cnt)
